package com.myles.kotobafloat;
import android.app.Activity;import android.os.*;import android.media.*;import android.widget.TextView;
public final class FocusGrabActivity extends Activity {private AudioManager manager;private AudioFocusRequest request;@Override public void onCreate(Bundle state){super.onCreate(state);TextView text=new TextView(this);text.setText("TEST ONLY: another app holds audio focus");setContentView(text);manager=(AudioManager)getSystemService(AUDIO_SERVICE);request=new AudioFocusRequest.Builder(AudioManager.AUDIOFOCUS_GAIN).setAudioAttributes(new AudioAttributes.Builder().setUsage(AudioAttributes.USAGE_MEDIA).setContentType(AudioAttributes.CONTENT_TYPE_MUSIC).build()).setOnAudioFocusChangeListener(c->{}).build();}@Override protected void onResume(){super.onResume();new Handler(Looper.getMainLooper()).postDelayed(()->manager.requestAudioFocus(request),150);}@Override protected void onDestroy(){manager.abandonAudioFocusRequest(request);super.onDestroy();}}
